<script setup>
import { computed, ref, defineAsyncComponent } from 'vue'
import DisclosurePanel from './DisclosurePanel.vue'
import SectionNav from './SectionNav.vue'
import { useResource } from './useResource.js'
import { comparisonInterval } from './resultIntervals.js'
import { useSectionFocus } from './useSectionFocus.js'
import InfoTip from './InfoTip.vue'
const props=defineProps({section:String})
useSectionFocus(()=>props.section,'results-')
defineEmits(['show-case'])
const V04Results=defineAsyncComponent(()=>import('./V04Results.vue'))
const V05Results=defineAsyncComponent(()=>import('./V05Results.vue'))
const BenchmarkOverview=defineAsyncComponent(()=>import('./BenchmarkOverview.vue'))
const ResearchDetails=defineAsyncComponent(()=>import('./ResearchDetails.vue'))
const {data:v04,error:e04,loading:l04,reload:r04}=useResource('/api/results_v04')
const {data:v05,error:e05,loading:l05,reload:r05}=useResource('/api/results_v05')
const {data:intervals}=useResource('/api/benchmarks')
const interval=(study,key)=>comparisonInterval(intervals.value,study==='v04'?'v04_test':'v05_cv',key)
const n=v=>v==null?'–':Number(v).toLocaleString('de-AT',{minimumFractionDigits:3,maximumFractionDigits:3})
const signed=v=>(v>0?'+':'')+n(v)
const active=ref('v04')
const cur=computed(()=>studies.value.find(x=>x.id===active.value))
const nav=[{id:'befund',label:'Hauptbefund'},{id:'kernaussagen',label:'Kernaussagen'},{id:'grenzen',label:'Grenzen'},{id:'vertiefung',label:'Vertiefung'}]
const labels={static:'Gelände allein',temporal:'Wetter allein',combined:'Gelände + Wetter'}
const studies=computed(()=>[
  {id:'v04',tag:'Hauptstudie · V0.4 · einmal ausgewerteter Test',title:'Ähnliche Hänge unterscheiden.',description:'Fünf topographisch ähnliche Vergleichshänge pro Ereignis. Der versiegelte Test wurde genau einmal ausgewertet.',data:v04.value,error:e04.value,loading:l04.value,reload:r04,events:v04.value?.counts.partition.sealed_test.events,units:v04.value?.counts.partition.sealed_test.units,primary:v04.value?.test.primary,rows:Object.entries(labels).map(([key,label])=>({key,label,value:v04.value?.test.results['conditional_logit/'+key]?.local_auc_weighted})),delta:v04.value?.test.primary.combined_minus_static},
  {id:'v05',tag:'Ergänzungsstudie · V0.5 · explorativ',title:'Den lokalen Hintergrund vergleichen.',description:'Zehn ungematchte Umgebungshänge pro Ereignis. Kreuzvalidierung auf bereits bekannten Ereignissen: Modelle werden wiederholt an zurückgehaltenen Gruppen geprüft; benachbarte Trainingspunkte bleiben ausgeschlossen.',data:v05.value,error:e05.value,loading:l05.value,reload:r05,events:v05.value?.cohort.events,units:v05.value?.cohort.units,primary:v05.value?.primary,rows:Object.entries(labels).map(([key,label])=>({key,label,value:v05.value?.purged['conditional_logit/'+key]?.local_auc_units})),delta:v05.value?.primary.combined_minus_static_rep1_bootstrap}
])
</script>
<template>
  <section class="page-intro compact results-intro"><p class="eyebrow">03 / Ergebnisse</p><h1>Das Gelände liefert Signal.<br><span>Der Wetternutzen bleibt offen.</span></h1></section>
  <SectionNav :items="nav"/>
  <section id="befund" class="study-result hero-result">
    <div class="study-switch" role="tablist" aria-label="Studie wählen"><button v-for="s in studies" :key="s.id" role="tab" type="button" :aria-selected="active===s.id" :class="{on:active===s.id}" @click="active=s.id"><strong>{{s.id==='v04'?'Hauptstudie':'Ergänzungsstudie'}}</strong><small>{{s.id==='v04'?'Fünf ähnliche Hänge · einmaliger Test':'Zehn Umgebungshänge · explorativ'}}</small></button></div>
    <div class="study-heading"><span class="study-label">{{cur.tag}}</span><span v-if="cur.data" class="study-sample">{{cur.events}} Ereignisse · <b>{{cur.units}} Abhängigkeitseinheiten</b></span></div>
    <p class="study-description">{{cur.description}}</p>
    <p v-if="cur.loading" role="status" class="loading">Gespeicherte Ergebnisse werden geladen …</p><div v-else-if="cur.error" role="alert" class="error"><p>{{cur.error}}</p><button @click="cur.reload">Erneut laden</button></div>
    <template v-else-if="cur.data"><div class="result-layout"><div class="comparison-chart"><div class="chart-scale"><span><InfoTip term="withinGroupAuc" label="Lokale AUC"/></span><span>0,5 · Zufall</span><span>1,0</span></div><div v-for="row in cur.rows" :key="row.key" class="comparison-row" :class="row.key"><div class="comparison-label"><span>{{row.label}}</span><strong>{{n(row.value)}}</strong></div><div class="comparison-track"><span :style="{width:row.value*100+'%'}"></span><i class="reference-line"></i></div><small v-if="interval(cur.id,row.key)" class="bar-interval">{{interval(cur.id,row.key).label}}: {{n(interval(cur.id,row.key).range[0])}}–{{n(interval(cur.id,row.key).range[1])}}</small><small v-else class="bar-interval">Intervall für diese Variante derzeit nicht verfügbar.</small></div><p class="chart-caption">{{cur.id==='v04'?'Gespeicherter Testwert · jede Einheit gleich gewichtet':'Median aus fünf Wiederholungen derselben Daten · keine fünf unabhängigen Studien'}}</p></div><aside class="uncertainty-panel"><template v-if="cur.id==='v04'"><p class="eyebrow">Gelände + Wetter</p><strong class="interval">{{n(cur.primary.ci95[0])}}–{{n(cur.primary.ci95[1])}}</strong><p>95-%-Intervall, Wiederziehen ganzer Abhängigkeitseinheiten.</p><p>Zufall: {{n(cur.primary.chance)}} · 95-%-Grenze zufälliger Rangfolgen: {{n(cur.primary.random_rank_null_q95)}}<br>p gegen Zufall: {{n(cur.data.test.results['conditional_logit/combined'].p_upper_vs_random_rank)}}</p></template><template v-else><p class="eyebrow">Gelände + Wetter</p><strong class="interval">{{n(cur.primary.ci95_rep1[0])}}–{{n(cur.primary.ci95_rep1[1])}}</strong><p>95-%-Intervall der <strong>ersten Wiederholung</strong>.</p><p>Spanne der fünf Wiederholungen: {{n(cur.primary.range[0])}}–{{n(cur.primary.range[1])}} (kein Konfidenzintervall).<br>Zufall: {{n(cur.primary.chance)}} · einfache Neigungsregel: {{n(cur.primary.slope_rule)}}</p></template></aside></div>
    <div class="weather-finding"><div><span>Bringt das Wetter zusätzlich etwas?</span><h3>Kein belegter Zusatznutzen.</h3></div><div><strong>{{signed(cur.delta.mean)}}</strong><p>Gelände + Wetter minus Gelände<br>95-%-Intervall: {{signed(cur.delta.ci95[0])}} bis {{signed(cur.delta.ci95[1])}}<span v-if="cur.id==='v05'"> · erste Wiederholung</span></p></div></div><p class="plain-note">Das gepaarte Intervall schließt null ein. Das beweist nicht, dass Wetter keinen Einfluss hat. Die ergänzende Studie nutzt leichtere Vergleichshänge und ist kein Leistungsfortschritt gegenüber dem Test.</p></template>
  </section>
  <section id="kernaussagen" class="takeaways"><p class="eyebrow">Kernaussagen</p><div class="three-columns"><article><span>01</span><h3>Gelände trägt Signal</h3><p>Die Rangfolge liegt klar über dem Zufall, in beiden Studien.</p></article><article><span>02</span><h3>Wetter: nicht belegt</h3><p>Der Zusatznutzen ist statistisch offen. Das ist ein gültiges Ergebnis.</p></article><article><span>03</span><h3>Meldebias möglich</h3><p>Das Modell nutzt Landbedeckung. Entdeckung und Dokumentation können mitwirken.</p></article></div></section>
  <section id="grenzen" class="limitations"><p class="eyebrow">Was die Aussage begrenzt</p><div class="three-columns"><article><h3>Wenige unabhängige Episoden</h3><p>Ein großer Sturm kann viele Ereignisse liefern. Im V0.4-Test stammen 243 der 300 Ereignisse aus der Stanz-Episode. Die Gewichtung nach Einheiten begrenzt diese Dominanz.</p></article><article><h3>Ein möglicher Meldeeffekt</h3><p>Das Modell nutzt Geländeform und Landbedeckung. Offenland und Siedlungsnähe können auch beeinflussen, wo Ereignisse entdeckt und dokumentiert werden.</p></article><article><h3>Keine Gefahrenprognose</h3><p>Die Resultate gelten für diese retrospektiven Vergleiche. Sie belegen weder geografische Übertragbarkeit noch eine reale Rutschungswahrscheinlichkeit.</p></article></div><p class="plain-note" v-if="v04">Zur Einordnung der Stanz-Dominanz: Bei gleicher Gewichtung aller Ereignisse beträgt die kombinierte lokale AUC {{n(v04.test.results['conditional_logit/combined'].local_auc_events)}} statt {{n(v04.test.primary.value)}} bei gleicher Gewichtung der {{v04.counts.partition.sealed_test.units}} Einheiten. Das ist eine ergänzende Sicht auf denselben Test.</p></section>
  <div id="vertiefung" class="deep-dives"><p class="eyebrow">Vertiefung</p><DisclosurePanel id="results-v04" title="V0.4: alle Modelle und Testdetails" subtitle="Gespeicherter versiegelter Test und getrennte Entwicklungsauswertung" :open="section==='v04'"><V04Results/></DisclosurePanel><DisclosurePanel id="results-v05" title="V0.5: Karten, Vergleichshänge und Modellmerkmale" subtitle="Reale Beispiele, alle Ereignisse und explorative Diagnosen" :open="section==='v05'"><V05Results/></DisclosurePanel><DisclosurePanel id="results-vergleich" title="Alle Untersuchungen im Vergleich" subtitle="V0 bis V0.5 · unterschiedliche Designs bleiben getrennt" :open="section==='vergleich'"><BenchmarkOverview/></DisclosurePanel><DisclosurePanel id="results-historie" title="Frühere Untersuchungen und Ereignis-Explorer" subtitle="Historische Baseline V0–V0.3 · Stabilität, Zufallsreferenz und Einzelfälle" :open="section==='historie'"><ResearchDetails mode="history" @show-case="$emit('show-case',$event)"/></DisclosurePanel></div>
  <a class="next-page" href="#/vorgehen/beispiel"><div><span>Selbst erkunden</span><strong>Die Forschung<br>an einem Hang verstehen.</strong></div><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M8 24h32M26 10l14 14-14 14"/></svg></a>
</template>
